changeSet.sql:
ALTER TABLE api_keys ADD COLUMN internal_service TEXT UNIQUE;
ALTER TABLE api_keys ADD CONSTRAINT api_keys_internal_service_scope CHECK (
    internal_service IS NULL OR (
        internal_service = 'agent' AND team_id IS NULL AND user_id IS NULL
        AND key_type = 'application' AND default_priority = 1
        AND use_custom_permissions = true
    )
);
INSERT INTO api_keys (key_value, name, key_type, environment, default_priority,
                      use_custom_permissions, internal_service)
VALUES ('internal-agent-' || gen_random_uuid()::text, 'Logos internal agent',
        'application', 'agent', 1, true, 'agent');

rollback.sql:
UPDATE api_keys SET is_active = false WHERE internal_service = 'agent';
ALTER TABLE api_keys DROP CONSTRAINT api_keys_internal_service_scope;
ALTER TABLE api_keys DROP COLUMN internal_service;
